#include <cstdio>
#include <cmath>
#include <vector>
#include <string>
#include "cJSON.h"
#include "lodepng.h"

static void die(const char* msg){
    fprintf(stderr, "Error: %s\n", msg);
    exit(1);
}

static std::vector<double> load_array(cJSON* root, const char* name){
    cJSON* arr = cJSON_GetObjectItemCaseSensitive(root, name);
    if(!arr || !cJSON_IsArray(arr)) die(("missing array " + std::string(name)).c_str());
    int n = cJSON_GetArraySize(arr);
    std::vector<double> v(n);
    for(int i=0;i<n;i++){
        cJSON* e = cJSON_GetArrayItem(arr,i);
        v[i] = e->valuedouble;
    }
    return v;
}

int main(int argc, char** argv){
